// Entire CLI extension for Pi
// Auto-generated by `entire enable --agent pi`
// Do not edit manually — changes will be overwritten on next install.
//
// Forwards Pi lifecycle events to `entire hooks pi <event>` so Entire can
// create checkpoints, capture transcripts, and offer rewind/resume.
//
// ENTIRE_CMD is replaced at install time by Entire's installer.

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { execFile } from "node:child_process";

export default function (pi: ExtensionAPI) {
  const ENTIRE_CMD = "__ENTIRE_CMD__";
  let pendingSkillEvents: Array<{ skill_name: string; invocation: string; timestamp: string }> = [];

  function fireHook(hookName: string, data: Record<string, unknown>): Promise<void> {
    return new Promise((resolve) => {
      try {
        const child = execFile(
          "sh",
          ["-c", `${ENTIRE_CMD} hooks pi ${hookName}`],
          { timeout: 10000, windowsHide: true },
          () => resolve(),
        );
        child.stdin?.end(JSON.stringify(data));
      } catch {
        // best effort — never block the agent on a hook failure
        resolve();
      }
    });
  }

  function parseSkillInvocation(text: string): { skill_name: string; invocation: string } | null {
    const match = text.trimStart().match(/^\/skill:([a-z0-9][a-z0-9-]{0,63})(?:\s|$)/);
    if (!match) return null;
    const invocation = text.trimStart().split(/\s+/, 1)[0] ?? `/skill:${match[1]}`;
    return { skill_name: match[1], invocation };
  }

  pi.on("input", async (event) => {
    const skill = parseSkillInvocation(event.text);
    if (skill) {
      pendingSkillEvents.push({ ...skill, timestamp: new Date().toISOString() });
    }
    return { action: "continue" };
  });

  // Agent-driven bash subprocesses inherit a real TTY but cannot answer
  // hook prompts. Disable git/Entire terminal prompts for bash calls so
  // Entire treats agent-driven commits as non-interactive.
  pi.on("tool_call", async (event) => {
    if (event.toolName !== "bash") return;
    const input = event.input as { command?: string };
    if (typeof input.command !== "string" || input.command.includes("GIT_TERMINAL_PROMPT=")) {
      return;
    }
    input.command = "export GIT_TERMINAL_PROMPT=0\n" + input.command;
  });

  pi.on("session_start", async (_event, ctx) => {
    await fireHook("session_start", {
      type: "session_start",
      cwd: ctx.cwd,
      session_file: ctx.sessionManager.getSessionFile(),
    });
  });

  pi.on("before_agent_start", async (event, ctx) => {
    const skillEvents = pendingSkillEvents;
    pendingSkillEvents = [];
    await fireHook("before_agent_start", {
      type: "before_agent_start",
      cwd: ctx.cwd,
      session_file: ctx.sessionManager.getSessionFile(),
      prompt: event.prompt,
      skill_events: skillEvents,
    });
  });

  pi.on("agent_end", async (_event, ctx) => {
    await fireHook("agent_end", {
      type: "agent_end",
      cwd: ctx.cwd,
      session_file: ctx.sessionManager.getSessionFile(),
    });
  });

  pi.on("session_shutdown", async () => {
    await fireHook("session_shutdown", { type: "session_shutdown" });
  });
}

// Package pi implements the Agent interface for the pi coding agent
// (https://github.com/earendil-works/pi-mono).
// The npm package the embedded extension imports a type from is
// `@earendil-works/pi-coding-agent`.
//
// This is an in-tree port of the previously-external entire-agent-pi plugin
// (github.com/entireio/external-agents/agents/entire-agent-pi). The behaviour
// matches the external version — most notably the active-branch resolution
// for Pi's tree-shaped sessions — but the integration is plumbed directly
// through the in-tree Agent / HookSupport / TokenCalculator / TranscriptAnalyzer
// interfaces rather than the external JSON-over-stdio protocol.
package pi

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// piHomeEnvVar overrides the default Pi home directory (~/.pi/agent).
// Pi itself reads this variable, so honoring it keeps Entire and Pi in
// agreement when a developer points Pi at a non-default home.
const piHomeEnvVar = "PI_CODING_AGENT_DIR"

// piSessionDirEnvVar lets tests redirect Pi's session lookup without
// touching the real ~/.pi/agent. Mirrors ENTIRE_TEST_<AGENT>_SESSION_DIR
// used by Codex.
const piSessionDirEnvVar = "ENTIRE_TEST_PI_SESSION_DIR"

//nolint:gochecknoinits // Agent self-registration is the intended pattern
func init() {
	agent.Register(agent.AgentNamePi, NewPiAgent)
}

// PiAgent implements agent.Agent for the pi coding agent.
//
//nolint:revive // PiAgent is clearer than Agent in this context
type PiAgent struct{}

// NewPiAgent returns a new Pi agent instance.
func NewPiAgent() agent.Agent {
	return &PiAgent{}
}

// --- Identity ---

func (a *PiAgent) Name() types.AgentName    { return agent.AgentNamePi }
func (a *PiAgent) Type() types.AgentType    { return agent.AgentTypePi }
func (a *PiAgent) Description() string      { return "Pi coding agent integration for Entire" }
func (a *PiAgent) IsPreview() bool          { return true }
func (a *PiAgent) ProtectedDirs() []string  { return []string{".pi"} }
func (a *PiAgent) ProtectedFiles() []string { return nil }

// DetectPresence reports whether pi is configured for *this repo*. We only
// check repo-local config (.pi/) and intentionally ignore $PATH — in-tree
// agents follow the convention used by Claude/Gemini/OpenCode where
// detection means "this repo is set up for this agent", not "this agent is
// installed somewhere on this machine". The external plugin uses the broader
// $PATH check because it can't see repo state; we don't have that limitation.
func (a *PiAgent) DetectPresence(ctx context.Context) (bool, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		repoRoot = "."
	}
	if _, err := os.Stat(filepath.Join(repoRoot, ".pi")); err == nil {
		return true, nil
	}
	return false, nil
}

// --- Transcript Storage (chunking) ---

// ReadTranscript reads a captured Pi JSONL session transcript from disk.
// SessionRef is the absolute path returned by captureTranscript().
func (a *PiAgent) ReadTranscript(sessionRef string) ([]byte, error) {
	if sessionRef == "" {
		return nil, errors.New("empty session ref")
	}
	//nolint:gosec // SessionRef from validated lifecycle hook input
	data, err := os.ReadFile(sessionRef)
	if err != nil {
		return nil, fmt.Errorf("read pi transcript %s: %w", sessionRef, err)
	}
	return data, nil
}

// ChunkTranscript splits a Pi JSONL transcript at line boundaries.
func (a *PiAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
	chunks, err := agent.ChunkJSONL(content, maxSize)
	if err != nil {
		return nil, fmt.Errorf("chunk pi transcript: %w", err)
	}
	return chunks, nil
}

// ReassembleTranscript concatenates JSONL chunks with newlines.
func (a *PiAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	return agent.ReassembleJSONL(chunks), nil
}

// --- Legacy methods ---

// GetSessionID extracts the session ID from a hook input.
func (a *PiAgent) GetSessionID(input *agent.HookInput) string {
	if input == nil {
		return ""
	}
	return input.SessionID
}

// GetSessionDir returns the directory where Pi natively stores session
// transcripts for repoPath: <piHome>/sessions/<encoded-repo-path>/.
//
// Pointing this at the native store (rather than the per-repo
// .entire/tmp/pi/ cache populated by the agent_end hook) is what lets
// `entire session attach <id>` resolve cold sessions — sessions that
// were never hooked, or whose hook capture failed. attach falls through
// to GetSessionDir + ResolveSessionFile when no SessionRef is recorded
// in metadata, and the live Pi store is the only place that always has
// the transcript on disk.
//
// Resolution order:
//  1. ENTIRE_TEST_PI_SESSION_DIR (test override; no encoding applied)
//  2. PI_CODING_AGENT_DIR (Pi's own override; encoding still applies)
//  3. ~/.pi/agent (default)
//
// The .entire/tmp/pi/ cache stays as a hook-internal detail —
// captureTranscript writes there and the TurnEnd event records that
// path as SessionRef in checkpoint metadata, so subsequent operations
// on hooked sessions go through the recorded SessionRef and never call
// GetSessionDir.
func (a *PiAgent) GetSessionDir(repoPath string) (string, error) {
	if override := os.Getenv(piSessionDirEnvVar); override != "" {
		return override, nil
	}
	home, err := resolvePiHome()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, "sessions", encodeRepoPathForPi(repoPath)), nil
}

// GetSessionBaseDir returns the base directory containing per-project
// session subdirectories. Used by attach's cross-project fallback
// (searchTranscriptInProjectDirs) when a session was started from a
// different cwd than the current worktree root.
func (a *PiAgent) GetSessionBaseDir() (string, error) {
	home, err := resolvePiHome()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, "sessions"), nil
}

// ResolveSessionFile returns the path to the Pi session file for
// agentSessionID in sessionDir. Pi names files <timestamp>_<id>.jsonl,
// so glob for the matching ID; on multiple matches the lexicographically
// latest (most recent timestamp) wins.
//
// Absolute paths pass through unchanged so hook payloads carrying live
// pi paths work without re-resolution. When no match exists, fall back
// to a deterministic non-existent path so downstream stat checks fail
// cleanly rather than panicking on an empty path.
func (a *PiAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
	if filepath.IsAbs(agentSessionID) {
		return agentSessionID
	}
	if path := findPiSessionByID(sessionDir, agentSessionID); path != "" {
		return path
	}
	if sessionDir == "" {
		return agentSessionID
	}
	return filepath.Join(sessionDir, agentSessionID+".jsonl")
}

// resolvePiHome returns Pi's home directory: $PI_CODING_AGENT_DIR or
// ~/.pi/agent.
func resolvePiHome() (string, error) {
	if dir := os.Getenv(piHomeEnvVar); dir != "" {
		return dir, nil
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("resolve user home: %w", err)
	}
	return filepath.Join(home, ".pi", "agent"), nil
}

// encodeRepoPathForPi encodes an absolute repo path into Pi's
// session-directory naming scheme: every path separator becomes '-',
// wrapped with '--' delimiters. /Users/foo/repo encodes as
// --Users-foo-repo--. Leading and trailing separators are absorbed so
// /a/b/ and /a/b encode the same way. Empty input returns "".
//
// Both '/' and '\\' are replaced regardless of host OS: on Windows,
// git rev-parse --show-toplevel returns forward slashes, but native
// Windows APIs use backslashes — a host-only replacement would leak
// the other form through and produce nested directories instead of a
// single name, breaking session lookup. filepath.ToSlash isn't enough
// because it only normalises the host's separator.
func encodeRepoPathForPi(repoPath string) string {
	if repoPath == "" {
		return ""
	}
	body := strings.NewReplacer("/", "-", `\`, "-").Replace(repoPath)
	body = strings.Trim(body, "-")
	return "--" + body + "--"
}

// findPiSessionByID globs sessionDir for *_<sessionID>.jsonl. Returns
// the lexicographically latest match (most recent timestamp) or "" when
// no match exists or sessionDir/sessionID is empty.
func findPiSessionByID(sessionDir, sessionID string) string {
	if sessionDir == "" || sessionID == "" {
		return ""
	}
	matches, err := filepath.Glob(filepath.Join(sessionDir, "*_"+sessionID+".jsonl"))
	if err != nil || len(matches) == 0 {
		return ""
	}
	sort.Strings(matches)
	return matches[len(matches)-1]
}

// ReadSession loads a captured Pi transcript and returns it as an AgentSession.
func (a *PiAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
	if input == nil || input.SessionRef == "" {
		return nil, errors.New("no session ref provided")
	}

	data, err := os.ReadFile(input.SessionRef)
	if err != nil {
		return nil, fmt.Errorf("read pi session: %w", err)
	}
	return &agent.AgentSession{
		AgentName:  a.Name(),
		SessionID:  input.SessionID,
		SessionRef: input.SessionRef,
		NativeData: data,
	}, nil
}

// WriteSession writes a captured Pi transcript back to disk so Pi can resume
// from it. Pi loads sessions from arbitrary paths via `pi --session <path>`,
// so a plain write is sufficient.
func (a *PiAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
	if session == nil {
		return errors.New("nil session")
	}
	if session.SessionRef == "" {
		return errors.New("session has empty SessionRef")
	}
	if len(session.NativeData) == 0 {
		return errors.New("session has empty NativeData")
	}
	if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o750); err != nil {
		return fmt.Errorf("create pi session dir: %w", err)
	}

	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
		return fmt.Errorf("write pi session file: %w", err)
	}
	return nil
}

// FormatResumeCommand returns the shell command to resume a specific Pi
// session by ID. Pi accepts a partial UUID via `pi --session <id>`. When no
// session is specified, fall back to `pi --continue` which reopens the most
// recent session.
func (a *PiAgent) FormatResumeCommand(sessionID string) string {
	id := strings.TrimSpace(sessionID)
	if id == "" {
		return "pi --continue"
	}
	return "pi --session " + id
}

package pi

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// Hook names — these match Pi's native event names exactly (snake_case),
// because the embedded TypeScript extension forwards `pi.on(<event>)` events
// directly. Keeping the names identical avoids a translation layer in the
// extension.
const (
	HookNameSessionStart     = "session_start"
	HookNameBeforeAgentStart = "before_agent_start"
	HookNameAgentEnd         = "agent_end"
	HookNameSessionShutdown  = "session_shutdown"
)

// HookNames returns the verbs registered as `entire hooks pi <name>`.
func (a *PiAgent) HookNames() []string {
	return []string{
		HookNameSessionStart,
		HookNameBeforeAgentStart,
		HookNameAgentEnd,
		HookNameSessionShutdown,
	}
}

// GetSupportedHooks maps Pi's native events to normalised lifecycle types.
//
//   - session_start       → SessionStart
//   - before_agent_start  → TurnStart
//   - agent_end           → TurnEnd
//   - session_shutdown    → (cleanup-only, no lifecycle event — see ParseHookEvent)
func (a *PiAgent) GetSupportedHooks() []agent.HookType {
	return []agent.HookType{
		agent.HookSessionStart,
		agent.HookUserPromptSubmit,
		agent.HookStop,
	}
}

// piHookPayload is the JSON the embedded TypeScript extension pipes to
// `entire hooks pi <event>` on stdin.
type piHookPayload struct {
	Type        string              `json:"type"`
	Cwd         string              `json:"cwd,omitempty"`
	SessionFile string              `json:"session_file,omitempty"`
	SessionID   string              `json:"session_id,omitempty"`
	Prompt      string              `json:"prompt,omitempty"`
	SkillEvents []piSkillEventInput `json:"skill_events,omitempty"`
}

type piSkillEventInput struct {
	SkillName  string `json:"skill_name"`
	Invocation string `json:"invocation"`
	Timestamp  string `json:"timestamp,omitempty"`
}

func piSkillEvents(in []piSkillEventInput) []agent.SkillEvent {
	if len(in) == 0 {
		return nil
	}
	out := make([]agent.SkillEvent, 0, len(in))
	for i, ev := range in {
		skillName := strings.TrimSpace(ev.SkillName)
		if skillName == "" {
			continue
		}
		invocation := strings.TrimSpace(ev.Invocation)
		if invocation == "" {
			invocation = "/skill:" + skillName
		}
		id := ""
		if ev.Timestamp != "" {
			id = fmt.Sprintf("pi-skill-%s-%s-%d", skillName, ev.Timestamp, i)
		}
		out = append(out, agent.SkillEvent{
			ID:        id,
			EventType: agent.SkillEventTypePromptInvocation,
			Skill: agent.SkillEventSkill{
				Name: skillName,
			},
			Source: agent.SkillEventSource{
				Agent:      string(agent.AgentNamePi),
				Signal:     agent.SkillSignalPiInputSlashCommand,
				Confidence: agent.SkillConfidenceExplicit,
			},
			Timestamp: ev.Timestamp,
			Native: map[string]string{
				"command": invocation,
			},
			Collapse: agent.SkillEventCollapse{
				Target:           agent.SkillCollapseTargetUserMessage,
				Label:            invocation,
				DefaultCollapsed: true,
			},
		})
	}
	return out
}

// ParseHookEvent translates a Pi hook invocation into a normalised lifecycle
// event. Implements agent.HookSupport.
func (a *PiAgent) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
	data, err := io.ReadAll(stdin)
	if err != nil {
		return nil, fmt.Errorf("read pi hook input: %w", err)
	}
	if len(data) == 0 {
		return nil, errors.New("empty pi hook input")
	}

	var payload piHookPayload
	if err := json.Unmarshal(data, &payload); err != nil {
		return nil, fmt.Errorf("parse pi hook payload: %w", err)
	}

	sessionID := payload.SessionID
	if sessionID == "" {
		sessionID = extractSessionIDFromPath(payload.SessionFile)
	}

	now := time.Now()

	switch hookName {
	case HookNameSessionStart:
		cacheSessionID(ctx, sessionID)
		return &agent.Event{
			Type:      agent.SessionStart,
			SessionID: sessionID,
			Timestamp: now,
		}, nil

	case HookNameBeforeAgentStart:
		// Pi emits before_agent_start with a fully-populated session ID, but
		// we cache it anyway to support the agent_end fallback below.
		if sessionID == "" {
			sessionID = readCachedSessionID(ctx)
		} else {
			cacheSessionID(ctx, sessionID)
		}
		// Provide the live Pi session file as SessionRef so state.TranscriptPath
		// is populated before any mid-turn commits. Without this, the
		// post-commit hook cannot condense when no shadow branch exists yet.
		return &agent.Event{
			Type:        agent.TurnStart,
			SessionID:   sessionID,
			SessionRef:  payload.SessionFile,
			Prompt:      payload.Prompt,
			Timestamp:   now,
			SkillEvents: piSkillEvents(payload.SkillEvents),
		}, nil

	case HookNameAgentEnd:
		if sessionID == "" {
			sessionID = readCachedSessionID(ctx)
		}
		// Capture the Pi JSONL into <repo>/.entire/tmp/pi/<id>.json so the
		// strategy has a stable transcript reference even if the user later
		// deletes Pi sessions. The pi/ subdir avoids colliding with paths
		// other agents (or test harnesses) stage under .entire/tmp/.
		sessionRef := captureTranscript(ctx, sessionID, payload.SessionFile)
		return &agent.Event{
			Type:       agent.TurnEnd,
			SessionID:  sessionID,
			SessionRef: sessionRef,
			Timestamp:  now,
		}, nil

	case HookNameSessionShutdown:
		// Cleanup-only: clear the cached session ID. We intentionally do NOT
		// emit SessionEnd here.
		//
		// Pi fires session_shutdown and agent_end on session teardown, and the
		// TypeScript extension dispatches both via separate `entire hooks pi …`
		// child processes (execFile is non-blocking). Child-process startup
		// ordering then decides which event reaches the lifecycle dispatcher
		// first; if session_shutdown wins, an emitted SessionEnd transitions
		// the session to "ended" before agent_end can save the linkable
		// checkpoint, leaving prepare-commit-msg with no session to attach a
		// trailer to and the user's commit unlinked.
		//
		// agent_end is the source of truth for "turn complete" (and, for Pi,
		// effectively "session over" for any single-turn `pi -p` invocation).
		// SessionEnd is left for the framework to derive from idle timeout or
		// the next SessionStart's stale-state cleanup.
		clearCachedSessionID(ctx)
		return nil, nil //nolint:nilnil // intentional: cleanup-only, no lifecycle event

	default:
		// Unknown / future hooks have no lifecycle significance.
		return nil, nil //nolint:nilnil // unknown hook = no lifecycle event (acceptable)
	}
}

// --- session ID cache ---
//
// Pi's `before_agent_start` event sometimes fires before `session_start` has
// completed cacheing the session ID (race during early extension load), and
// `agent_end` may fire after Pi has torn down its session manager. We cache
// the active session ID at session_start time so subsequent hooks can recover
// it.

const activeSessionFile = "pi-active-session"

// piHookCacheSubdir is the subdirectory under .entire/tmp/ where hook
// flow caches the active-session ID file and the agent_end transcript
// snapshot. Agent-specific (not just .entire/tmp/) so other agents'
// integration tests and tooling don't shadow each other under the cache
// root.
const piHookCacheSubdir = "pi"

// resolveSessionDir returns the per-repo hook cache directory used by
// cacheSessionID / readCachedSessionID / clearCachedSessionID and
// captureTranscript.
//
// This is intentionally distinct from PiAgent.GetSessionDir, which
// points at Pi's native session store (~/.pi/agent/sessions/...) so
// cold attach can resolve transcripts that were never hook-captured.
// The cache here is hook-internal and only reachable via Pi hooks
// firing; the framework records the cached path as SessionRef in
// checkpoint metadata, so subsequent operations on hooked sessions go
// through the recorded path rather than re-resolving via GetSessionDir.
func resolveSessionDir(ctx context.Context) string {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		//nolint:forbidigo // fallback when no git repo (tests run outside repos)
		wd, wdErr := os.Getwd()
		if wdErr != nil {
			return filepath.Join(paths.EntireTmpDir, piHookCacheSubdir)
		}
		root = wd
	}
	return filepath.Join(root, paths.EntireTmpDir, piHookCacheSubdir)
}

func cacheSessionID(ctx context.Context, id string) {
	if id == "" {
		return
	}
	dir := resolveSessionDir(ctx)
	if err := os.MkdirAll(dir, 0o750); err != nil {
		logging.Debug(ctx, "pi: cache session id mkdir", slog.String("err", err.Error()))
		return
	}

	if err := os.WriteFile(filepath.Join(dir, activeSessionFile), []byte(id), 0o600); err != nil {
		logging.Debug(ctx, "pi: cache session id write", slog.String("err", err.Error()))
	}
}

func readCachedSessionID(ctx context.Context) string {
	dir := resolveSessionDir(ctx)
	//nolint:gosec // path constructed from validated repo root
	data, err := os.ReadFile(filepath.Join(dir, activeSessionFile))
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(data))
}

func clearCachedSessionID(ctx context.Context) {
	dir := resolveSessionDir(ctx)
	_ = os.Remove(filepath.Join(dir, activeSessionFile))
}

// captureTranscript copies the Pi JSONL session file to
// <repo>/.entire/tmp/pi/<id>.json so Entire has a stable transcript
// reference. Returns the path to the cached file, or "" if either input is
// missing. The pi/ namespace under .entire/tmp/ is intentional — see
// GetSessionDir / piHookCacheSubdir for the rationale.
func captureTranscript(ctx context.Context, sessionID, piSessionFile string) string {
	if sessionID == "" || piSessionFile == "" {
		return ""
	}
	dir := resolveSessionDir(ctx)
	if err := os.MkdirAll(dir, 0o750); err != nil {
		logging.Warn(ctx, "pi: capture transcript mkdir failed",
			slog.String("dir", dir), slog.String("err", err.Error()))
		return ""
	}
	dst := filepath.Join(dir, sessionID+".json")
	//nolint:gosec // G703: piSessionFile from trusted Pi extension stdin payload
	data, err := os.ReadFile(piSessionFile)
	if err != nil {
		logging.Warn(ctx, "pi: capture transcript read failed",
			slog.String("src", piSessionFile), slog.String("err", err.Error()))
		return ""
	}
	//nolint:gosec // G703: dst constructed from validated session ID inside .entire/tmp
	if err := os.WriteFile(dst, data, 0o600); err != nil {
		logging.Warn(ctx, "pi: capture transcript write failed",
			slog.String("dst", dst), slog.String("err", err.Error()))
		return ""
	}
	return dst
}

// extractSessionIDFromPath extracts the UUID from a Pi session filename.
// Pattern: <timestamp>_<uuid>.jsonl → returns <uuid>
// Falls back to the basename without extension if the pattern doesn't match.
func extractSessionIDFromPath(p string) string {
	if p == "" {
		return ""
	}
	base := filepath.Base(p)
	base = strings.TrimSuffix(base, ".jsonl")
	if i := strings.LastIndex(base, "_"); i >= 0 {
		return base[i+1:]
	}
	return base
}

